async getSlots(): Promise<ResourceSlotsDto[]> {
  const slots = await this.manager.find(Slot, {
    order: { resourceId: 'ASC', start: 'ASC' },
  });

  const resourceSlotsById = new Map<number, IResourceSlotsWithConflicts>();

  for (const slot of slots) {
    let resource = resourceSlotsById.get(slot.resourceId);

    if (!resource) {
      resource = {
        resourceId: slot.resourceId,
        slots: [],
      };
      resourceSlotsById.set(slot.resourceId, resource);
    }

    resource.slots.push({ ...slot, conflicts: [] });
  }

  const result = [...resourceSlotsById.values()];

  for (const resource of result) {
    this.computeConflicts(resource.slots);
  }

  return result;
}

/**
 * Populates each slot's conflicts with the other slots on the same
 * resource whose half-open [start, end) intervals overlap it, so
 * back-to-back slots do not conflict. Conflicts are symmetric: both
 * overlapping slots list each other.
 *
 * Expects slots sorted ascending by start, which allows the inner scan
 * to stop at the first slot starting at or after the current slot's end.
 * ISO-8601 datetime strings compare chronologically as plain strings.
 */
private computeConflicts(sortedSlots: ISlotWithConflicts[]): void {
  for (let i = 0; i < sortedSlots.length; i++) {
    const current = sortedSlots[i];

    for (let j = i + 1; j < sortedSlots.length; j++) {
      const next = sortedSlots[j];

      if (next.start >= current.end) {
        break;
      }

      current.conflicts.push(this.toConflictDto(next));
      next.conflicts.push(this.toConflictDto(current));
    }
  }
}

/**
 * Copies a slot's own fields without its conflicts array, keeping the
 * serialized response flat and free of circular references.
 */
private toConflictDto(slot: SlotDto): SlotDto {
  return {
    id: slot.id,
    name: slot.name,
    start: slot.start,
    end: slot.end,
    resourceId: slot.resourceId,
  };
}

type SlotWithConflicts = SlotDto & { conflicts: SlotDto[] };

type ResourceSlotsWithConflicts = Omit<ResourceSlotsDto, 'slots'> & {
  slots: SlotWithConflicts[];
};

